package de.jplag.options;

import de.jplag.Language;

public class JPlagLanguageOptionAccess {

    private final JPlagLanguageOptions languageOptions;

    public JPlagLanguageOptionAccess(JPlagLanguageOptions languageOptions) {
        this.languageOptions = languageOptions;
    }

    public String[] getFileSuffixes() {
        return languageOptions.getFileSuffixes();
    }

    public String getLanguageIdentifier() {
        return languageOptions.getLanguageIdentifier();
    }

    public Language getLanguage() {
        return languageOptions.getLanguage();
    }

    public Verbosity getVerbosity() {
        return languageOptions.getVerbosity();
    }

    public void setFileSuffixes(String[] fileSuffixes) {
        languageOptions.setFileSuffixes(fileSuffixes);
    }

    public void setLanguage(Language language) {
        languageOptions.setLanguage(language);
    }

    public void setLanguageDefaults(Language language) {
        languageOptions.setLanguageDefaults(language);
    }

    public void setVerbosity(Verbosity verbosity) {
        languageOptions.setVerbosity(verbosity);
    }
}

package de.jplag.options;

import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Optional;
import java.util.Set;

import de.jplag.Language;
import de.jplag.clustering.ClusteringOptions;
import de.jplag.strategy.ComparisonMode;

public class JPlagOptions {

    public static final ComparisonMode DEFAULT_COMPARISON_MODE = JPlagComparisonOptions.DEFAULT_COMPARISON_MODE;
    public static final float DEFAULT_SIMILARITY_THRESHOLD = JPlagComparisonOptions.DEFAULT_SIMILARITY_THRESHOLD;
    public static final int DEFAULT_SHOWN_COMPARISONS = JPlagComparisonOptions.DEFAULT_SHOWN_COMPARISONS;
    public static final Charset CHARSET = StandardCharsets.UTF_8;

    private final JPlagComparisonOptions comparisonOptions = new JPlagComparisonOptions();
    private final JPlagSubmissionOptions submissionOptions;
    private final JPlagSubmissionOptionAccess submissionOptionAccess;
    private final JPlagLanguageOptions languageOptions;
    private final JPlagLanguageOptionAccess languageOptionAccess;
    private final JPlagClusteringOptions clusteringOptions = new JPlagClusteringOptions();

    /**
     * Constructor with required attributes.
     * @param languageIdentifier the identifier of the language to use. If set to {@code null} you have to use
     * {@link #setLanguage(Language)} to set the language programmatically.
     */
    public JPlagOptions(List<String> submissionDirectories, List<String> oldSubmissionDirectories, String languageIdentifier) {
        this.submissionOptions = new JPlagSubmissionOptions(submissionDirectories, oldSubmissionDirectories);
        this.submissionOptionAccess = new JPlagSubmissionOptionAccess(submissionOptions);
        this.languageOptions = new JPlagLanguageOptions(languageIdentifier, comparisonOptions);
        this.languageOptionAccess = new JPlagLanguageOptionAccess(languageOptions);
    }

    public JPlagComparisonOptions getComparisonOptions() {
        return comparisonOptions;
    }

    public JPlagSubmissionOptions getSubmissionOptions() {
        return submissionOptions;
    }

    public JPlagSubmissionOptionAccess getSubmissionOptionAccess() {
        return submissionOptionAccess;
    }

    public JPlagLanguageOptions getLanguageOptions() {
        return languageOptions;
    }

    public JPlagLanguageOptionAccess getLanguageOptionAccess() {
        return languageOptionAccess;
    }

    public ComparisonMode getComparisonMode() {
        return comparisonOptions.getComparisonMode();
    }

    public int getMaximumNumberOfComparisons() {
        return comparisonOptions.getMaximumNumberOfComparisons();
    }

    public Integer getMinimumTokenMatch() {
        return comparisonOptions.getMinimumTokenMatch();
    }

    public SimilarityMetric getSimilarityMetric() {
        return comparisonOptions.getSimilarityMetric();
    }

    public float getSimilarityThreshold() {
        return comparisonOptions.getSimilarityThreshold();
    }

    public boolean isDebugParser() {
        return comparisonOptions.isDebugParser();
    }

    public ClusteringOptions getClusteringOptions() {
        return clusteringOptions.getClusteringOptions();
    }

    public Optional<String> getBaseCodeSubmissionName() {
        return submissionOptionAccess.getBaseCodeSubmissionName();
    }

    public Set<String> getExcludedFiles() {
        return submissionOptionAccess.getExcludedFiles();
    }

    public String getExclusionFileName() {
        return submissionOptionAccess.getExclusionFileName();
    }

    public List<String> getSubmissionDirectories() {
        return submissionOptionAccess.getSubmissionDirectories();
    }

    public List<String> getOldSubmissionDirectories() {
        return submissionOptionAccess.getOldSubmissionDirectories();
    }

    public String getSubdirectoryName() {
        return submissionOptionAccess.getSubdirectoryName();
    }

    public boolean hasBaseCode() {
        return submissionOptionAccess.hasBaseCode();
    }

    public void setBaseCodeSubmissionName(String baseCodeSubmissionName) {
        submissionOptionAccess.setBaseCodeSubmissionName(baseCodeSubmissionName);
    }

    public void setExcludedFiles(Set<String> excludedFiles) {
        submissionOptionAccess.setExcludedFiles(excludedFiles);
    }

    public void setExclusionFileName(String exclusionFileName) {
        submissionOptionAccess.setExclusionFileName(exclusionFileName);
    }

    public void setSubmissionDirectories(List<String> submissionDirectories) {
        submissionOptionAccess.setSubmissionDirectories(submissionDirectories);
    }

    public void setOldSubmissionDirectories(List<String> oldSubmissionDirectories) {
        submissionOptionAccess.setOldSubmissionDirectories(oldSubmissionDirectories);
    }

    public void setSubdirectoryName(String subdirectoryName) {
        submissionOptionAccess.setSubdirectoryName(subdirectoryName);
    }

    public void setComparisonMode(ComparisonMode comparisonMode) {
        comparisonOptions.setComparisonMode(comparisonMode);
    }

    public void setDebugParser(boolean debugParser) {
        comparisonOptions.setDebugParser(debugParser);
    }

    public void setMaximumNumberOfComparisons(int maximumNumberOfComparisons) {
        comparisonOptions.setMaximumNumberOfComparisons(maximumNumberOfComparisons);
    }

    public void setMinimumTokenMatch(Integer minimumTokenMatch) {
        comparisonOptions.setMinimumTokenMatch(minimumTokenMatch);
    }

    public void setSimilarityMetric(SimilarityMetric similarityMetric) {
        comparisonOptions.setSimilarityMetric(similarityMetric);
    }

    public void setSimilarityThreshold(float similarityThreshold) {
        comparisonOptions.setSimilarityThreshold(similarityThreshold);
    }

    public void setClusteringOptions(ClusteringOptions clusteringOptions) {
        this.clusteringOptions.setClusteringOptions(clusteringOptions);
    }
}
